-- Table: Community_Member
CREATE TABLE Community_Member (member_id INT, wrhs_address VARCHAR (100), f_name VARCHAR (50) NOT NULL, m_name VARCHAR (50), l_name VARCHAR (50) NOT NULL, mbr_address VARCHAR (255), phone VARCHAR (20), email VARCHAR (100), start_date DATE, mbr_status VARCHAR (50), wrhs_distance INTEGER, PRIMARY KEY (member_id), FOREIGN KEY (wrhs_address) REFERENCES Warehouse (wrhs_address) ON UPDATE CASCADE);

-- Table: Drone
CREATE TABLE Drone (manufacturer VARCHAR (100), drone_id INT PRIMARY KEY, year INT, load_capacity DECIMAL (10, 2), warranty_expir DATE, wrhs_address VARCHAR (100), order_num INT, FOREIGN KEY (wrhs_address) REFERENCES Warehouse (wrhs_address) ON UPDATE CASCADE, FOREIGN KEY (order_num) REFERENCES Purchase_Order (order_num));

-- Table: Drone_Performs_Delivery
CREATE TABLE Drone_Performs_Delivery (rental_id INT, drone_id INT, miles_flown DECIMAL(10, 2), PRIMARY KEY (drone_id, rental_id), FOREIGN KEY (rental_id) REFERENCES Rental_Transaction (rental_id), FOREIGN KEY (drone_id) REFERENCES Drone (drone_id));

-- Table: Drone_Performs_Return
CREATE TABLE Drone_Performs_Return (rental_id INT, drone_id INT, PRIMARY KEY (drone_id, rental_id), FOREIGN KEY (rental_id) REFERENCES Rental_Transaction (rental_id), FOREIGN KEY (drone_id) REFERENCES Drone (drone_id));

-- Table: Drone_Undergo_Maint
CREATE TABLE Drone_Undergo_Maint (maint_id INT, drone_id INT, PRIMARY KEY (maint_id, drone_id), FOREIGN KEY (maint_id) REFERENCES Maintenance_Record (maint_id), FOREIGN KEY (drone_id) REFERENCES Drone (drone_id));

-- Table: Employee
CREATE TABLE Employee (f_name VARCHAR (50) NOT NULL, m_name VARCHAR (50), l_name VARCHAR (50) NOT NULL, ssn VARCHAR (9), wrhs_address VARCHAR (100), role VARCHAR (50), phone_no VARCHAR (20), email VARCHAR (100), hire_date DATE, pay_rate DECIMAL (10, 2), hrs_worked DECIMAL (10, 2), PRIMARY KEY (ssn), FOREIGN KEY (wrhs_address) REFERENCES Warehouse (wrhs_address) ON UPDATE CASCADE);

-- Table: Equip_Undergo_Maint
CREATE TABLE Equip_Undergo_Maint (maint_id INT, equipment_id INT, PRIMARY KEY (maint_id, equipment_id), FOREIGN KEY (maint_id) REFERENCES Maintenance_Record (maint_id), FOREIGN KEY (equipment_id) REFERENCES Equipment (equipment_id));

-- Table: Equipment
CREATE TABLE Equipment (type VARCHAR (255), year INT, order_num INT, wrhs_address VARCHAR (100), equipment_id INT PRIMARY KEY ON CONFLICT IGNORE, status VARCHAR (50), location VARCHAR (100), manufacturer VARCHAR (100), weight DECIMAL (10, 2), warranty_expiration DATE, FOREIGN KEY (wrhs_address) REFERENCES Equipment (wrhs_address) ON UPDATE CASCADE, FOREIGN KEY (order_num) REFERENCES Purchase_Order (order_num));

-- Table: Maintenance_Record
CREATE TABLE Maintenance_Record (maint_id INT, empolyee_ssn VARCHAR (9), maint_date DATE, issue VARCHAR (255), action VARCHAR (255), next_due_date DATE, cost DECIMAL (10, 2), maint_hrs DECIMAL (10, 2), PRIMARY KEY (maint_id), FOREIGN KEY (empolyee_ssn) REFERENCES Employee (ssn) ON UPDATE CASCADE);

-- Table: Purchase_Order
CREATE TABLE Purchase_Order (quantity INT, order_num INT, wrhs_address VARCHAR (100), value DECIMAL (10, 2), est_arrive_date DATE, actual_arrive_date DATE, PRIMARY KEY (order_num), FOREIGN KEY (wrhs_address) REFERENCES Warehouse (wrhs_address));

-- Table: Rating_And_Review
CREATE TABLE Rating_And_Review (rating INT, member_id INT, equipment_id INT, comments TEXT, date DATE NOT NULL, PRIMARY KEY (member_id, equipment_id, date), FOREIGN KEY (member_id) REFERENCES Community_Member (member_id), FOREIGN KEY (equipment_id) REFERENCES Equipment (equipment_id));

-- Table: Rental_Transaction
CREATE TABLE Rental_Transaction (checkout_date DATETIME, rental_id INT, equipment_id INT NOT NULL, member_id INT NOT NULL, due_date DATE, return_date DATE, rental_fee DECIMAL (10, 2), PRIMARY KEY (rental_id), FOREIGN KEY (equipment_id) REFERENCES Equipment (equipment_id) ON UPDATE CASCADE, FOREIGN KEY (member_id) REFERENCES Community_Member (member_id) ON UPDATE CASCADE);

-- Table: Warehouse
CREATE TABLE Warehouse (phone VARCHAR (20), wrhs_address VARCHAR (100), manager_ssn VARCHAR (9), equipment_cap INT, drone_cap INT, PRIMARY KEY (wrhs_address), FOREIGN KEY (manager_ssn) REFERENCES Employee (ssn) ON UPDATE CASCADE);

-- Table: Warehouse_Houses_Drone
CREATE TABLE Warehouse_Houses_Drone (start_date DATE, wrhs_address VARCHAR (100), drone_id INT, PRIMARY KEY (wrhs_address, drone_id), FOREIGN KEY (wrhs_address) REFERENCES Warehouse (wrhs_address) ON UPDATE CASCADE, FOREIGN KEY (drone_id) REFERENCES Drone (drone_id) ON UPDATE CASCADE);

-- View: Manager_Info
CREATE VIEW Manager_Info AS
    SELECT warehouse.Wrhs_address,
           CONCAT(Employee.F_name, ' ', Employee.L_name) AS Manager_name,
           AVG(Employee.Pay_rate * Employee.Hrs_worked) AS Avg_Salary
      FROM Warehouse,
           Employee
     WHERE Warehouse.Wrhs_address = Employee.Wrhs_address AND
           Warehouse.Manager_ssn = Employee.Ssn
     GROUP BY Warehouse.wrhs_address,
              Manager_name;

-- View: Warranty_Expring_2026
CREATE VIEW Warranty_Expring_2026 AS
    SELECT warehouse.wrhs_address,
           COUNT(drone.drone_id) AS Num_of_Drones
      FROM warehouse,
           drone
     WHERE warehouse.wrhs_address = drone.wrhs_address AND
           Drone.warranty_expir LIKE '2026-%'
     GROUP BY Warehouse.wrhs_address;

COMMIT TRANSACTION;
